from typing import List

def max_skill_sum(n: int, skills: List[int], levels: List[int]) -> int:
    max_sum = 0
    for i in range(1 << n):
        if bin(i).count('1') < 2:
            continue
        mask = i
        valid = True
        for j in range(n):
            if mask & (1 << j):
                for k in range(j + 1, n):
                    if mask & (1 << k):
                        if (skills[j] & ~skills[k]) == skills[j] or (skills[k] & ~skills[j]) == skills[k]:
                            valid = False
                            break
                if not valid:
                    break
        if valid:
            current_sum = sum(levels[j] for j in range(n) if mask & (1 << j))
            max_sum = max(max_sum, current_sum)
    return max_sum

