def max_skill_sum(n, a, b):
    # Convert binary representations to sets of known algorithms
    known_algorithms = [set(range(60)) if x == 0 else {j for j in range(60) if x & (1 << j)} for x in a]

    # Function to check if a subset of students can work together calmly
    def can_work_together(subset):
        for i in range(len(subset)):
            for j in range(i + 1, len(subset)):
                if all(known_algorithms[subset[i]].issuperset(known_algorithms[student]) or known_algorithms[subset[j]].issuperset(known_algorithms[student]) for student in subset):
                    return False
        return True

    # Try all subsets of size at least 2
    max_sum = 0
    for r in range(2, n + 1):
        for subset in combinations(range(n), r):
            if can_work_together(subset):
                current_sum = sum(b[i] for i in subset)
                if current_sum > max_sum:
                    max_sum = current_sum

    return max_sum

