def max_calm_group_sum(n, a, b):
    # Iterate through all possible subsets of students
    max_sum = 0
    for i in range(1, 1 << n):
        group = [j for j in range(n) if i & (1 << j)]
        if len(group) >= 2:
            calm = True
            for x in group:
                for y in group:
                    if x != y and (a[x] & ~a[y]) == 0:
                        calm = False
                        break
                if not calm:
                    break
            if calm:
                max_sum = max(max_sum, sum(b[j] for j in group))
    return max_sum

